// ─── File: DelayedSchedulerDemo.java ───
// Delayed job scheduler using a Redis-style sorted set (score = execute_at)
// instead of polling the whole DB every second. Future jobs are skipped free.
import java.util.*;
import java.util.logging.*;

public class DelayedSchedulerDemo {
    private static final Logger log = Logger.getLogger("SCHED");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        long now = 1_000_000L;  // simulated clock (ms)
        SortedSetScheduler zset = new SortedSetScheduler();

        // Schedule jobs at various future times (ZADD score = execute_at).
        zset.schedule(new Job("reminder:SAV2001", "REMINDER", now + 1000));
        zset.schedule(new Job("settle-retry:TXN88", "SETTLE_RETRY", now + 2000));
        zset.schedule(new Job("hold-expire:CUR3001", "HOLD_EXPIRE", now + 5000));
        zset.schedule(new Job("reminder:CUR3001", "REMINDER", now + 1000));
        log.info(() -> "Scheduled " + zset.size() + " jobs (ordered by execute_at)");

        // Tick 1: clock at now+1000 — only the two due jobs returned, future skipped free.
        long t1 = now + 1000;
        List<Job> due1 = zset.claimDue(t1);   // atomic ZRANGEBYSCORE -inf t1 + ZREM
        log.info(() -> "Tick @" + t1 + ": claimed " + due1.size() + " due job(s): " + ids(due1));
        log.info(() -> "Remaining future jobs untouched: " + zset.size());

        // Tick 2: clock at now+2000 — the settle-retry becomes due.
        long t2 = now + 2000;
        List<Job> due2 = zset.claimDue(t2);
        log.info(() -> "Tick @" + t2 + ": claimed " + due2.size() + " due job(s): " + ids(due2));

        // Time bucketing demo: group by minute so each tick inspects one bucket only.
        MinuteBucketIndex buckets = new MinuteBucketIndex();
        buckets.add(new Job("reminder:SAV2001", "REMINDER", 1_000_000L));
        buckets.add(new Job("reminder:CUR3001", "REMINDER", 1_000_000L));
        buckets.add(new Job("hold-expire:X", "HOLD_EXPIRE", 1_060_000L)); // next minute
        log.info(() -> "Minute bucket @1,000,000 has " + buckets.bucketSize(1_000_000L)
                + " jobs; next-minute bucket NOT scanned this tick");
    }
    static String ids(List<Job> jobs) {
        StringBuilder sb = new StringBuilder();
        for (Job j : jobs) sb.append(j.id()).append(" ");
        return sb.toString().trim();
    }
}

// ─── model/Job.java ───
class Job {
    private final String id, type; private final long executeAtMs;
    Job(String id, String type, long executeAtMs) { this.id = id; this.type = type; this.executeAtMs = executeAtMs; }
    String id() { return id; } String type() { return type; } long executeAtMs() { return executeAtMs; }
}

// ─── index/SortedSetScheduler.java (Redis ZSET: score = execute_at) ───
class SortedSetScheduler {
    private static final Logger log = Logger.getLogger("SCHED");
    // TreeMap ordered by score models a Redis sorted set; member = job id.
    private final TreeMap<Long, List<Job>> byScore = new TreeMap<>();
    private int count = 0;

    void schedule(Job job) {   // ZADD due_jobs <executeAtMs> <jobId>
        byScore.computeIfAbsent(job.executeAtMs(), k -> new ArrayList<>()).add(job);
        count++;
    }
    int size() { return count; }

    // Atomic claim: ZRANGEBYSCORE -inf now + ZREM (single Lua in real Redis).
    // Returns only due jobs; FUTURE jobs are never scanned — skipped for free.
    List<Job> claimDue(long nowMs) {
        List<Job> due = new ArrayList<>();
        SortedMap<Long, List<Job>> head = byScore.headMap(nowMs, true); // scores <= now
        Iterator<Map.Entry<Long, List<Job>>> it = head.entrySet().iterator();
        while (it.hasNext()) {
            Map.Entry<Long, List<Job>> e = it.next();
            due.addAll(e.getValue());
            count -= e.getValue().size();
            it.remove();  // ZREM — removed so no other worker re-claims
        }
        return due;
    }
}

// ─── index/MinuteBucketIndex.java (time bucketing) ───
class MinuteBucketIndex {
    private final Map<Long, List<Job>> buckets = new HashMap<>();
    private long bucketKey(long ms) { return (ms / 60_000L) * 60_000L; }  // floor to the minute
    void add(Job job) { buckets.computeIfAbsent(bucketKey(job.executeAtMs()), k -> new ArrayList<>()).add(job); }
    int bucketSize(long ms) { return buckets.getOrDefault(bucketKey(ms), List.of()).size(); }
}

// ─── runner/SchedulerLoop.java ───
class SchedulerLoop {
    private static final Logger log = Logger.getLogger("SCHED");
    private final SortedSetScheduler zset;
    SchedulerLoop(SortedSetScheduler zset) { this.zset = zset; }
    void tick(long nowMs) {
        List<Job> due = zset.claimDue(nowMs);
        due.forEach(j -> log.info(() -> "enqueue to worker queue: " + j.id() + " (" + j.type() + ")"));
    }
}

